/**
 * Model directory for the Magpie gateway.
 *
 * Single source: `GET {baseUrl}/models` already curates the servable set
 * with full per-model metadata (modalities, native endpoints, reasoning
 * ladders, context limits). There is no paid/free filter — everything listed
 * is exposed. A disk cache plus a compile-time static snapshot covers gateway
 * outages (the plugin still registers, the picker still lists).
 *
 * The gateway guards that endpoint with the same Bearer key as inference, so
 * every fetch here carries it: a keyless refresh is answered 401 and the
 * picker silently keeps the static snapshot instead of the live directory.
 *
 * `baseUrl` is the versioned API root (default `http://127.0.0.1:3425/v1`),
 * never an origin: the gateway may move to `/v2`, and the plugin must not know
 * that version.
 */

export interface MagpieModelEntry {
  id: string
  displayName: string
  contextWindow?: number
  maxTokens?: number
  /** Whether the gateway accepts image input for this model. */
  image: boolean
  /** Raw gateway `native_endpoints` (may be empty when undisclosed). */
  nativeEndpoints: string[]
  /**
   * Raw gateway `magpie_prefers`: the path the gateway says it is best asked
   * on for this model (`/v1/responses`, `/v1/chat/completions`). Absent when
   * the gateway said nothing or said something the plugin cannot read.
   */
  prefers?: string
  /** Whether the gateway reports thinking support. */
  reasoning: boolean
  /** Effort allowlist from `supported_reasoning_levels` (canonical order). */
  efforts?: string[]
}

/** The two wires the plugin speaks; anything else the gateway has to translate. */
export type EndpointApi = 'openai-completions' | 'openai-responses'

/**
 * Thinking levels the gateway uses. pi-ai natively understands the minimal→max
 * ladder; `none` (thinking disabled) and `ultra` (beyond max, e.g. Terra) are
 * gateway extensions the adapter forwards verbatim on the Responses /
 * completions wire instead of clamping.
 */
export const KNOWN_EFFORTS = ['minimal', 'low', 'medium', 'high', 'xhigh', 'max'] as const
export const EXTENDED_EFFORTS = ['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max', 'ultra'] as const

export type KnownEffort = (typeof KNOWN_EFFORTS)[number]
export type ExtendedEffort = (typeof EXTENDED_EFFORTS)[number]

/** Picker display order: `none` (disable) first, then increasing strength. */
const EFFORT_ORDER: readonly string[] = ['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max', 'ultra']

const EFFORT_LABELS: Record<string, { name: string; description: string }> = {
  none: { name: 'None', description: '关闭思考，直接回答' },
  minimal: { name: 'Minimal', description: '最少思考，最快' },
  low: { name: 'Low', description: '轻量思考，适合简单问答' },
  medium: { name: 'Medium', description: '默认档位，均衡质量与速度' },
  high: { name: 'High', description: '深度思考，适合复杂编码' },
  xhigh: { name: 'Extra high', description: '超高思考强度' },
  max: { name: 'Max', description: '最强思考（pi-ai 档位），最慢' },
  ultra: { name: 'Ultra', description: '极限思考（网关直通），最慢最贵' },
}

export interface ReasoningEffortChoice {
  id: string
  name: string
  description?: string
}

/** Normalize one gateway effort spelling; unknown spellings are dropped. */
export function normalizeEffort(raw: unknown): string | undefined {
  if (typeof raw !== 'string') return undefined
  const level = raw.trim().toLowerCase()
  return (EFFORT_ORDER as readonly string[]).includes(level) ? level : undefined
}

/** Canonicalize an effort list: keep known spellings, dedupe, order canonically. */
export function canonicalEfforts(values: readonly unknown[] | undefined): string[] | undefined {
  if (!Array.isArray(values)) return undefined
  const out: string[] = []
  for (const value of values) {
    const level = normalizeEffort(typeof value === 'object' && value !== null ? (value as { effort?: unknown }).effort ?? value : value)
    if (level !== undefined && !out.includes(level)) out.push(level)
  }
  if (out.length === 0) return undefined
  return EFFORT_ORDER.filter((level) => out.includes(level))
}

/** Build picker efforts for an allowlist (display order = none→minimal→…→ultra). */
export function effortsFor(efforts: readonly string[] | undefined): ReasoningEffortChoice[] {
  const allowed = new Set(efforts ?? [])
  return EFFORT_ORDER.filter((level) => allowed.has(level)).map((level) => {
    const label = EFFORT_LABELS[level] ?? { name: level, description: '' }
    return { id: level, name: label.name, description: label.description }
  })
}

/**
 * pi-ai `thinkingLevelMap` for an effort allowlist. `off: null` is
 * load-bearing: without it pi-ai falls back to `reasoning.effort: 'none'`
 * on the Responses lane, which the gateway rejects with 400. Every
 * non-listed known level maps to null so `getSupportedThinkingLevels` hides
 * it and `clampThinkingLevel` folds stale values to the nearest listed one.
 * Gateway extensions (`none`/`ultra`) never enter the map — the adapter
 * forwards them via `provider.stream` instead of `streamSimple`.
 */
export function thinkingLevelMapFor(efforts: readonly string[] | undefined): Record<string, string | null> {
  const allowed = new Set(efforts ?? [])
  const map: Record<string, string | null> = { off: null }
  for (const level of KNOWN_EFFORTS) map[level] = allowed.has(level) ? level : null
  return map
}

/**
 * The wire one gateway path names, if it is one of the two the plugin speaks.
 *
 * Matched by whole path segment (`/v1/chat/completions`, `/v1/responses`,
 * possibly behind a prefix), never by substring: `/v1/responses/compact` and
 * the like are other endpoints and must not read as a supported wire.
 */
export function apiOfPath(path: string): EndpointApi | undefined {
  if (!/\/responses$/.test(path)) {
    return /\/chat\/completions$/.test(path) ? 'openai-completions' : undefined
  }
  return 'openai-responses'
}

/**
 * True when the model must go through `/v1/responses` instead of chat
 * completions on `native_endpoints` alone: the gateway lists responses as the
 * only native endpoint the plugin speaks (Muse Spark, Codex/Grok lanes).
 * Anything advertising `/v1/chat/completions` — including multi-endpoint
 * models — rides the completions lane for better tool support.
 */
export function requiresResponsesApiEntry(nativeEndpoints: readonly string[]): boolean {
  return modelApiForEntry(nativeEndpoints) === 'openai-responses'
}

/**
 * pi-ai `model.api` for one model: the wire every request for it rides, and
 * the one its replayed assistant history is tagged with. The model id is
 * never touched.
 *
 * Decided from what the gateway's ordinary `GET /models` says —
 * `native_endpoints` (the paths it relays as-is) and `magpie_prefers` (where
 * it is best asked) — with Chat Completions first whenever the two do not
 * settle it:
 *
 * - One supported native endpoint: it is used, whatever the preference says.
 * - Several: the preference is adopted only when it is *literally one of the
 *   listed paths* — the gateway named that path as best — and the plugin
 *   speaks it; otherwise Chat.
 * - None listed: nothing is known about what the gateway relays, so either
 *   supported preference may be adopted; missing or illegal → Chat.
 * - Listed, but nothing the plugin supports (e.g. Anthropic only): the
 *   gateway translates whatever arrives, exactly as before — a preference
 *   for a wire it did not list is not adopted, and the turn stays on Chat.
 *
 * @param nativeEndpoints - the raw `native_endpoints` list.
 * @param prefers - the raw `magpie_prefers` path, when the gateway gave one.
 * @returns the wire to send this model's requests on.
 */
export function modelApiForEntry(nativeEndpoints: readonly string[], prefers?: string): EndpointApi {
  const supported = new Set<EndpointApi>()
  for (const endpoint of nativeEndpoints) {
    const api = apiOfPath(endpoint)
    if (api !== undefined) supported.add(api)
  }
  if (supported.size === 1) return [...supported][0]!
  if (supported.size === 0) {
    // An undisclosed list leaves the preference as the only thing to go on;
    // a list that names nothing the plugin speaks is left alone (Chat), so
    // the gateway's translation keeps receiving what it always did.
    return nativeEndpoints.length === 0 ? (prefers === undefined ? undefined : apiOfPath(prefers)) ?? 'openai-completions' : 'openai-completions'
  }
  // Several supported wires: the preference has to be the gateway's own
  // listed path, not merely a path that names a listed wire (a `/v2/responses`
  // the gateway did not list is not what it said it prefers).
  const preferred = prefers !== undefined && nativeEndpoints.includes(prefers) ? apiOfPath(prefers) : undefined
  return preferred !== undefined && supported.has(preferred) ? preferred : 'openai-completions'
}

/**
 * The compat heuristic for an id the directory does not list at all: the
 * Codex/Grok/Muse lanes read as Responses, everything else as Chat. Only a
 * capability hint (`requiresResponsesApi`); never what a request is sent on.
 */
const LEGACY_RESPONSES_ID = /muse-spark|codex\/|grok/i

/** The gateway separates a model name from its group with a middle dot. */
const LABEL_GROUP_SEPARATOR = '\u00B7'

/** Capitalize only the first character; preserve the rest of a gateway/id group. */
function capitalizeGroup(group: string): string {
  return group.length === 0 ? '' : group[0]!.toLocaleUpperCase() + group.slice(1)
}

/** Derive a fallback group from the id's first slash-delimited segment. */
function groupFromId(id: string): string {
  const prefix = id.split('/', 1)[0]?.trim() ?? ''
  return capitalizeGroup(prefix)
}

/**
 * The one label both the DSH model picker and this plugin's settings page show.
 * The model name is exactly `display_name`. Prefer the group after the last
 * middle dot in `magpie_label`; if it is absent or empty, capitalize the first
 * character of the id's first path segment as the fallback group.
 */
export function displayNameFor(raw: Record<string, unknown>): string {
  const id = typeof raw.id === 'string' ? raw.id : ''
  const name = typeof raw.display_name === 'string' ? raw.display_name.trim() : ''
  if (name === '') return id
  const label = typeof raw.magpie_label === 'string' ? raw.magpie_label.trim() : ''
  const at = label.lastIndexOf(LABEL_GROUP_SEPARATOR)
  const parsedGroup = at >= 0 ? label.slice(at + 1).trim() : ''
  const idGroup = groupFromId(id)
  // Routing ids are the source of truth for these two lanes; their gateway
  // label group is generic and must not replace the explicit route prefix.
  const routingPrefix = id.startsWith('auto/') || id.startsWith('group/')
  const group = routingPrefix ? idGroup : parsedGroup || idGroup
  if (group === '') return id
  return `${group}/${name}`
}

/** Decode one gateway model object into a catalog entry. */
export function decodeModel(raw: unknown): MagpieModelEntry | undefined {
  if (!raw || typeof raw !== 'object') return undefined
  const record = raw as Record<string, unknown>
  const id = record.id
  if (typeof id !== 'string' || id.length === 0) return undefined
  const num = (value: unknown): number | undefined =>
    typeof value === 'number' && Number.isFinite(value) && value > 0 ? Math.floor(value) : undefined
  const displayName = displayNameFor(record)
  const contextWindow = num(record.context_window) ?? num(record.context_length) ?? num(record.max_input_tokens)
  const maxTokens = num(record.max_output_tokens)
  const modalities = record.modalities as { input?: unknown } | undefined
  const inputModalities = Array.isArray(modalities?.input) ? modalities.input.map(String).map((s) => s.toLowerCase()) : []
  const image = inputModalities.includes('image')
  const nativeEndpoints = Array.isArray(record.native_endpoints)
    ? (record.native_endpoints as unknown[]).filter((e): e is string => typeof e === 'string')
    : []
  // `magpie_prefers` is the gateway's own path spelling. Only a path the
  // plugin can read as one of its two wires is kept; anything else (a bare
  // protocol name, a number, an empty string) is dropped rather than stored
  // and guessed at later — the wire then stays on the native-endpoint rule.
  const rawPrefers = record.magpie_prefers
  const prefersPath = typeof rawPrefers === 'string' ? rawPrefers.trim() : ''
  const prefers = prefersPath !== '' && apiOfPath(prefersPath) !== undefined ? prefersPath : undefined
  const reasoning = record.reasoning === true
  const levels = record.supported_reasoning_levels
  const efforts = Array.isArray(levels)
    ? canonicalEfforts(levels.map((entry) => (entry as { effort?: unknown })?.effort ?? entry))
    : undefined
  return {
    id,
    displayName,
    ...(contextWindow !== undefined ? { contextWindow } : {}),
    ...(maxTokens !== undefined ? { maxTokens } : {}),
    image,
    nativeEndpoints,
    ...(prefers !== undefined ? { prefers } : {}),
    reasoning,
    ...(efforts !== undefined ? { efforts } : {}),
  }
}

/** Decode the full gateway `/v1/models` payload into entries keyed by id. */
export function decodeMagpieModels(data: unknown): Map<string, MagpieModelEntry> {
  const result = new Map<string, MagpieModelEntry>()
  if (!data || typeof data !== 'object') return result
  const payload = data as { data?: unknown }
  if (!Array.isArray(payload.data)) return result
  for (const raw of payload.data) {
    const entry = decodeModel(raw)
    if (entry && !result.has(entry.id)) result.set(entry.id, entry)
  }
  return result
}

